import React, { useState, useEffect } from 'react';

interface Test {
  id: string;
  name: string;
  suite: string;
  type: string;
  priority: number;
  tags: string[];
  file_path?: string;
  created_at?: string;
  updated_at?: string;
  config?: any;
  setup?: any;
  execution?: any;
  expectations?: any;
  cleanup?: any;
}

interface Job {
  id: string;
  name: string;
  status: string;
  created_at: string;
  test_count: number;
}

interface TestSuite {
  id: string;
  name: string;
  test_ids: string[];
  created_at: string;
}

type ViewType = 'dashboard' | 'tests' | 'jobs' | 'suites' | 'results';

function App() {
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [tests, setTests] = useState<Test[]>([]);
  const [jobs, setJobs] = useState<Job[]>([]);
  const [testSuites, setTestSuites] = useState<TestSuite[]>([]);
  const [selectedTests, setSelectedTests] = useState<Set<string>>(new Set());
  const [selectedTest, setSelectedTest] = useState<Test | null>(null);
  const [loading, setLoading] = useState(true);
  const [showSuiteModal, setShowSuiteModal] = useState(false);
  const [suiteFormData, setSuiteFormData] = useState({ name: '', description: '' });
  const [showFullJson, setShowFullJson] = useState(false);

  useEffect(() => {
    Promise.all([
      fetch('http://localhost:6002/api/tests?limit=1000').then(res => res.json()),
      fetch('http://localhost:6002/api/jobs').then(res => res.json()).catch(() => [])
    ]).then(([testsData, jobsData]) => {
      setTests(testsData);
      setJobs(jobsData);
      setLoading(false);
    }).catch(err => {
      console.error('Failed to fetch data:', err);
      setLoading(false);
    });
  }, []);

  const handleSelectAll = () => {
    if (selectedTests.size === tests.length) {
      setSelectedTests(new Set());
    } else {
      setSelectedTests(new Set(tests.map(t => t.id)));
    }
  };

  const handleSelectSuite = (suite: string) => {
    const suiteTests = tests.filter(t => t.suite === suite);
    const suiteTestIds = suiteTests.map(t => t.id);
    const newSelected = new Set(selectedTests);

    // Check if all tests in this suite are selected
    const allSelected = suiteTestIds.every(id => selectedTests.has(id));

    if (allSelected) {
      // Deselect all in this suite
      suiteTestIds.forEach(id => newSelected.delete(id));
    } else {
      // Select all in this suite
      suiteTestIds.forEach(id => newSelected.add(id));
    }

    setSelectedTests(newSelected);
  };

  const handleSelectTest = (testId: string) => {
    const newSelected = new Set(selectedTests);
    if (newSelected.has(testId)) {
      newSelected.delete(testId);
    } else {
      newSelected.add(testId);
    }
    setSelectedTests(newSelected);
  };

  const handleCreateJob = async () => {
    if (selectedTests.size === 0) return;

    const payload = {
      name: `Manual Run - ${new Date().toLocaleString()}`,
      test_ids: Array.from(selectedTests),
      configuration: {
        parallel_workers: 2,
        timeout: 300
      }
    };

    try {
      const response = await fetch('http://localhost:6002/api/jobs', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      const job = await response.json();
      alert(`Job created: ${job.id}`);
      setSelectedTests(new Set());
      // Refresh jobs
      fetch('http://localhost:6002/api/jobs').then(res => res.json()).then(setJobs);
    } catch (err) {
      alert('Failed to create job');
    }
  };

  const handleSaveAsTestSuite = () => {
    if (selectedTests.size === 0) return;

    const name = prompt('Enter test suite name:');
    if (!name) return;

    const newSuite: TestSuite = {
      id: `TS_${Date.now()}`,
      name,
      test_ids: Array.from(selectedTests),
      created_at: new Date().toISOString()
    };

    setTestSuites([...testSuites, newSuite]);
    localStorage.setItem('testSuites', JSON.stringify([...testSuites, newSuite]));
    alert('Test suite saved!');
  };

  // Load saved test suites from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('testSuites');
    if (saved) {
      setTestSuites(JSON.parse(saved));
    }
  }, []);

  if (loading) {
    return <div style={{ padding: '20px' }}>Loading...</div>;
  }

  // Group tests by suite
  const testsBySuite = tests.reduce((acc, test) => {
    if (!acc[test.suite]) acc[test.suite] = [];
    acc[test.suite].push(test);
    return acc;
  }, {} as Record<string, Test[]>);

  const stats = {
    totalTests: tests.length,
    totalSuites: Object.keys(testsBySuite).length,
    byPriority: tests.reduce((acc, test) => {
      acc[test.priority] = (acc[test.priority] || 0) + 1;
      return acc;
    }, {} as Record<number, number>),
    byType: tests.reduce((acc, test) => {
      acc[test.type] = (acc[test.type] || 0) + 1;
      return acc;
    }, {} as Record<string, number>)
  };

  const priorityColors: Record<number, string> = {
    5: '#dc3545',
    4: '#fd7e14',
    3: '#ffc107',
    2: '#28a745',
    1: '#007bff'
  };

  const navStyle = {
    backgroundColor: '#343a40',
    padding: '0',
    marginBottom: '20px'
  };

  const navItemStyle = (active: boolean) => ({
    display: 'inline-block',
    padding: '15px 20px',
    color: active ? '#fff' : '#adb5bd',
    backgroundColor: active ? '#007bff' : 'transparent',
    cursor: 'pointer',
    borderRight: '1px solid #495057'
  });

  return (
    <div style={{ fontFamily: 'Arial, sans-serif' }}>
      {/* Navigation */}
      <div style={navStyle}>
        <div style={{ maxWidth: '1200px', margin: '0 auto' }}>
          <div style={navItemStyle(currentView === 'dashboard')} onClick={() => setCurrentView('dashboard')}>
            Dashboard
          </div>
          <div style={navItemStyle(currentView === 'tests')} onClick={() => setCurrentView('tests')}>
            Test Selection
          </div>
          <div style={navItemStyle(currentView === 'jobs')} onClick={() => setCurrentView('jobs')}>
            Jobs ({jobs.length})
          </div>
          <div style={navItemStyle(currentView === 'suites')} onClick={() => setCurrentView('suites')}>
            Test Suites ({testSuites.length})
          </div>
          <div style={navItemStyle(currentView === 'results')} onClick={() => setCurrentView('results')}>
            Results
          </div>
        </div>
      </div>

      <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '0 20px' }}>
        {/* Dashboard View */}
        {currentView === 'dashboard' && (
          <div>
            <h1>Test Management Dashboard</h1>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px', marginBottom: '30px' }}>
              <div style={{ backgroundColor: '#f8f9fa', padding: '20px', borderRadius: '8px', border: '1px solid #dee2e6' }}>
                <h3 style={{ margin: '0 0 10px 0', fontSize: '16px', color: '#6c757d' }}>Total Tests</h3>
                <p style={{ fontSize: '32px', margin: 0, fontWeight: 'bold' }}>{stats.totalTests}</p>
              </div>

              <div style={{ backgroundColor: '#f8f9fa', padding: '20px', borderRadius: '8px', border: '1px solid #dee2e6' }}>
                <h3 style={{ margin: '0 0 10px 0', fontSize: '16px', color: '#6c757d' }}>Test Suites</h3>
                <p style={{ fontSize: '32px', margin: 0, fontWeight: 'bold' }}>{stats.totalSuites}</p>
              </div>

              <div style={{ backgroundColor: '#f8f9fa', padding: '20px', borderRadius: '8px', border: '1px solid #dee2e6' }}>
                <h3 style={{ margin: '0 0 10px 0', fontSize: '16px', color: '#6c757d' }}>Active Jobs</h3>
                <p style={{ fontSize: '32px', margin: 0, fontWeight: 'bold' }}>{jobs.filter(j => j.status === 'running').length}</p>
              </div>

              <div style={{ backgroundColor: '#f8f9fa', padding: '20px', borderRadius: '8px', border: '1px solid #dee2e6' }}>
                <h3 style={{ margin: '0 0 10px 0', fontSize: '16px', color: '#6c757d' }}>Saved Suites</h3>
                <p style={{ fontSize: '32px', margin: 0, fontWeight: 'bold' }}>{testSuites.length}</p>
              </div>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
              <div style={{ backgroundColor: '#f8f9fa', padding: '20px', borderRadius: '8px', border: '1px solid #dee2e6' }}>
                <h3>Tests by Priority</h3>
                {Object.entries(stats.byPriority).sort(([a], [b]) => Number(b) - Number(a)).map(([priority, count]) => (
                  <div key={priority} style={{ marginBottom: '10px' }}>
                    <span style={{
                      display: 'inline-block',
                      width: '60px',
                      padding: '2px 8px',
                      backgroundColor: priorityColors[Number(priority)],
                      color: 'white',
                      borderRadius: '12px',
                      fontSize: '12px',
                      textAlign: 'center'
                    }}>
                      P{priority}
                    </span>
                    <span style={{ marginLeft: '10px' }}>{count} tests</span>
                  </div>
                ))}
              </div>

              <div style={{ backgroundColor: '#f8f9fa', padding: '20px', borderRadius: '8px', border: '1px solid #dee2e6' }}>
                <h3>Tests by Type</h3>
                {Object.entries(stats.byType).map(([type, count]) => (
                  <div key={type} style={{ marginBottom: '10px' }}>
                    <span style={{ fontWeight: 'bold' }}>{type}:</span>
                    <span style={{ marginLeft: '10px' }}>{count} tests</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Test Selection View */}
        {currentView === 'tests' && (
          <div>
            <h1>Test Selection</h1>
            <p style={{ marginBottom: '20px', color: '#6c757d' }}>
              Total: {tests.length} tests across {Object.keys(testsBySuite).length} suites
            </p>

            <div style={{ marginBottom: '20px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div>
                <label style={{ marginRight: '20px' }}>
                  <input 
                    type="checkbox" 
                    checked={selectedTests.size === tests.length && tests.length > 0}
                    onChange={handleSelectAll}
                    style={{ marginRight: '5px' }}
                  />
                  Select All ({selectedTests.size} of {tests.length} selected)
                </label>
              </div>
              <div>
                <button 
                  onClick={handleSaveAsTestSuite}
                  disabled={selectedTests.size === 0}
                  style={{
                    padding: '10px 20px',
                    backgroundColor: '#6c757d',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: selectedTests.size > 0 ? 'pointer' : 'not-allowed',
                    marginRight: '10px'
                  }}
                >
                  Save as Test Suite
                </button>
                <button 
                  onClick={handleCreateJob}
                  disabled={selectedTests.size === 0}
                  style={{
                    padding: '10px 20px',
                    backgroundColor: selectedTests.size > 0 ? '#007bff' : '#ccc',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: selectedTests.size > 0 ? 'pointer' : 'not-allowed'
                  }}
                >
                  Create Job
                </button>
              </div>
            </div>

            <div style={{ backgroundColor: '#f8f9fa', borderRadius: '8px', overflow: 'hidden' }}>
              {Object.entries(testsBySuite).map(([suite, suiteTests]) => {
                const allSelected = suiteTests.every(t => selectedTests.has(t.id));
                const someSelected = suiteTests.some(t => selectedTests.has(t.id));

                return (
                  <div key={suite} style={{ marginBottom: '20px' }}>
                    <h3 style={{ 
                      backgroundColor: '#e9ecef', 
                      padding: '10px 15px', 
                      margin: 0,
                      fontSize: '16px',
                      fontWeight: 'normal',
                      display: 'flex',
                      justifyContent: 'space-between',
                      alignItems: 'center'
                    }}>
                      <span>{suite} ({suiteTests.length} tests)</span>
                      <label>
                        <input 
                          type="checkbox"
                          checked={allSelected}
                          ref={input => {
                            if (input) {
                              input.indeterminate = !allSelected && someSelected;
                            }
                          }}
                          onChange={() => handleSelectSuite(suite)}
                          style={{ marginRight: '5px' }}
                        />
                        Select all in {suite}
                      </label>
                    </h3>
                    <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                      <thead>
                        <tr style={{ backgroundColor: '#f8f9fa' }}>
                          <th style={{ padding: '10px', textAlign: 'left', width: '40px' }}></th>
                          <th style={{ padding: '10px', textAlign: 'left' }}>Test ID</th>
                          <th style={{ padding: '10px', textAlign: 'left' }}>Name</th>
                          <th style={{ padding: '10px', textAlign: 'left' }}>Type</th>
                          <th style={{ padding: '10px', textAlign: 'center' }}>Priority</th>
                          <th style={{ padding: '10px', textAlign: 'left' }}>Tags</th>
                          <th style={{ padding: '10px', textAlign: 'center' }}>Details</th>
                        </tr>
                      </thead>
                      <tbody>
                        {suiteTests.map(test => (
                          <tr key={test.id} style={{ borderBottom: '1px solid #dee2e6' }}>
                            <td style={{ padding: '10px', textAlign: 'center' }}>
                              <input 
                                type="checkbox"
                                checked={selectedTests.has(test.id)}
                                onChange={() => handleSelectTest(test.id)}
                              />
                            </td>
                            <td style={{ padding: '10px', fontFamily: 'monospace', fontSize: '13px' }}>{test.id}</td>
                            <td style={{ padding: '10px' }}>{test.name}</td>
                            <td style={{ padding: '10px' }}>{test.type}</td>
                            <td style={{ padding: '10px', textAlign: 'center' }}>
                              <span style={{
                                display: 'inline-block',
                                padding: '2px 8px',
                                backgroundColor: priorityColors[test.priority],
                                color: 'white',
                                borderRadius: '12px',
                                fontSize: '12px'
                              }}>
                                P{test.priority}
                              </span>
                            </td>
                            <td style={{ padding: '10px' }}>
                              {test.tags.slice(0, 3).map((tag, idx) => (
                                <span key={idx} style={{
                                  display: 'inline-block',
                                  padding: '2px 6px',
                                  backgroundColor: '#e9ecef',
                                  borderRadius: '3px',
                                  fontSize: '11px',
                                  marginRight: '4px'
                                }}>
                                  {tag}
                                </span>
                              ))}
                              {test.tags.length > 3 && (
                                <span style={{ fontSize: '11px', color: '#6c757d' }}>
                                  +{test.tags.length - 3} more
                                </span>
                              )}
                            </td>
                            <td style={{ padding: '10px', textAlign: 'center' }}>
                              <button
                                onClick={() => setSelectedTest(test)}
                                style={{
                                  padding: '4px 8px',
                                  backgroundColor: '#007bff',
                                  color: 'white',
                                  border: 'none',
                                  borderRadius: '4px',
                                  fontSize: '12px',
                                  cursor: 'pointer'
                                }}
                              >
                                View
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Jobs View */}
        {currentView === 'jobs' && (
          <div>
            <h1>Jobs</h1>
            <p>Jobs management coming soon...</p>
          </div>
        )}

        {/* Test Suites View */}
        {currentView === 'suites' && (
          <div>
            <h1>Test Suites</h1>
            {testSuites.length === 0 ? (
              <p>No saved test suites. Create one from the Test Selection view.</p>
            ) : (
              <div>
                {testSuites.map(suite => (
                  <div key={suite.id} style={{ 
                    backgroundColor: '#f8f9fa', 
                    padding: '15px', 
                    marginBottom: '10px',
                    borderRadius: '8px',
                    border: '1px solid #dee2e6'
                  }}>
                    <h3>{suite.name}</h3>
                    <p>{suite.test_ids.length} tests • Created: {new Date(suite.created_at).toLocaleString()}</p>
                    <button
                      onClick={() => {
                        setSelectedTests(new Set(suite.test_ids));
                        setCurrentView('tests');
                      }}
                      style={{
                        padding: '8px 16px',
                        backgroundColor: '#007bff',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: 'pointer'
                      }}
                    >
                      Load Tests
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Results View */}
        {currentView === 'results' && (
          <div>
            <h1>Test Results</h1>
            <p>Results view coming soon...</p>
          </div>
        )}

        {/* Test Detail Modal */}
        {selectedTest && (
          <div style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: 'rgba(0,0,0,0.5)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 1000
          }}>
            <div style={{
              backgroundColor: 'white',
              padding: '30px',
              borderRadius: '8px',
              maxWidth: '600px',
              width: '90%',
              maxHeight: '80vh',
              overflow: 'auto'
            }}>
              <h2>{selectedTest.name}</h2>
              <p><strong>ID:</strong> {selectedTest.id}</p>
              <p><strong>Suite:</strong> {selectedTest.suite}</p>
              <p><strong>Type:</strong> {selectedTest.type}</p>
              <p><strong>Priority:</strong> P{selectedTest.priority}</p>
              <p><strong>Tags:</strong> {selectedTest.tags.join(', ')}</p>
              {selectedTest.file_path && (
                <p><strong>File:</strong> <code style={{ fontSize: '12px' }}>{selectedTest.file_path}</code></p>
              )}
              {selectedTest.created_at && (
                <p><strong>Created:</strong> {new Date(selectedTest.created_at).toLocaleString()}</p>
              )}
              <button
                onClick={() => setSelectedTest(null)}
                style={{
                  marginTop: '20px',
                  padding: '10px 20px',
                  backgroundColor: '#6c757d',
                  color: 'white',
                  border: 'none',
                  borderRadius: '4px',
                  cursor: 'pointer'
                }}
              >
                Close
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default App;
